 .hero-title__line{white-space:nowrap}
 .hero-lead{font-size:1rem;line-height:1.85}
 .hero-visual{width:100%;justify-self:stretch}
 .hero-meta{grid-template-columns:1fr;gap:8px;margin-top:30px;padding-top:16px}
