 .section-header,.split-grid,.page-header-grid,.about-story-grid,.values-head,.contact-layout,.footer-main{grid-template-columns:1fr}
 .section-header__copy,.page-header .wp-block-post-excerpt{justify-self:start}
 .section-header__title h2,.section-header>h2,.news-head h2,.cms-demo h2,.band h2,.about-story h2,.values-head h2,.process-section h2,.contact-guide h2,.footer-cta h2,.company-stance h2{font-size:clamp(1.8rem,8vw,2.35rem)}
 .cms-demo-grid{grid-template-columns:1fr;gap:32px}
