/* Responsive and accessibility safety layer.
 * Issue #11 moved global type/spacing decisions to layout-system.css; keep this
 * file focused on resilient wrapping, interaction states and structural fallbacks. */
:root{
 --yohaku-muted-strong:#465b53;
 --yohaku-focus:#456b26;
 --yohaku-focus-dark:#d9ec9b;
}
body,button,input,textarea,select{
 font-family:system-ui,-apple-system,BlinkMacSystemFont,"Hiragino Sans","Yu Gothic Medium","Yu Gothic",Meiryo,sans-serif;
}
body,p,li{line-break:strict;word-break:normal;overflow-wrap:normal}
.break-anywhere{overflow-wrap:anywhere;word-break:break-word}
h1,h2,h3{text-wrap:wrap}
.hero-visual figcaption,.hero-meta p,.copyright,.brand-subtitle{color:var(--yohaku-muted-strong)}
.demo-note{font-size:12px;color:var(--yohaku-muted-strong)}
.case-note{font-size:12px;color:#c6d7ca}

.skip-link{
 position:fixed;
 top:12px;
 left:16px;
 z-index:10000;
 transform:translateY(-180%);
 padding:12px 16px;
 border-radius:4px;
 background:#fff;
 color:var(--yohaku-forest);
 font-weight:800;
 text-decoration:none;
 box-shadow:0 8px 24px rgba(13,43,37,.2);
}
.skip-link:focus-visible{transform:translateY(0);outline:3px solid var(--yohaku-focus);outline-offset:3px}
.demo-case a:focus-visible,.demo-case button:focus-visible,.band a:focus-visible,.band button:focus-visible,.footer-wrap a:focus-visible{
 outline-color:var(--yohaku-focus-dark);
}
.wp-block-navigation a[aria-current="page"]::after,.wp-block-navigation .current-menu-item>a::after{right:0;height:2px}
.wp-block-navigation a[aria-current="page"],.wp-block-navigation .current-menu-item>a{font-weight:800}
.service-row{position:relative}
.service-row:focus-within{background:rgba(217,236,155,.14)}
.service-row__title-link{display:inline-block;color:inherit;text-decoration:none;min-height:44px;padding-block:5px}
.service-row__title-link:hover{text-decoration:underline;text-decoration-thickness:2px}
.service-row__arrow{min-width:44px;min-height:44px;display:flex;align-items:flex-start;justify-content:flex-end}
.service-row__arrow span{display:inline-flex;min-width:44px;min-height:44px;align-items:center;justify-content:center}

/* Lower-page editorial components. Their global type scale and measures come
 * from layout-system.css; these rules only describe each component's structure. */
.company-intro,.resources-intro{margin-bottom:52px}
.company-profile,.resource-grid{border-top:1px solid var(--yohaku-rule-strong)}
.company-profile__row{display:grid;grid-template-columns:minmax(120px,3fr) minmax(0,9fr);gap:32px;padding:22px 0;border-bottom:1px solid var(--yohaku-rule)}
.company-profile__key{font-size:12px;font-weight:800;letter-spacing:.08em;color:var(--yohaku-muted-strong);margin:0}
.company-profile__value{margin:0;line-height:1.85}
.company-stance{margin-top:64px;padding:36px 0;border-top:1px solid var(--yohaku-rule-strong)}
.company-stance h2{margin:0 0 20px}
.company-stance p{max-width:var(--yohaku-measure-reading,46rem)}
.resource-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0}
.resource-card{padding:32px 28px;border-bottom:1px solid var(--yohaku-rule)}
.resource-card:nth-child(even){border-left:1px solid var(--yohaku-rule)}
.resource-card__meta{font-weight:800;color:var(--yohaku-muted-strong);margin-bottom:12px}
.resource-card h2{margin:0 0 14px}
.resource-card p{line-height:1.85}
.resource-card .wp-block-buttons{margin-top:24px}

.post-hero{padding-top:clamp(52px,7vw,88px)}
.post-meta{display:flex;flex-wrap:wrap;gap:12px 18px;align-items:center;margin-bottom:14px}
.post-meta .wp-block-post-date,.post-meta .wp-block-post-terms{font-size:12px;font-weight:700;color:var(--yohaku-muted-strong)}
.post-hero h1{margin:14px 0 34px}
.post-hero .wp-block-post-featured-image{margin-top:0;margin-bottom:0}
.post-hero .wp-block-post-featured-image img{width:100%;aspect-ratio:16/9;object-fit:cover}
.post-body{margin-inline:auto;padding-top:clamp(48px,6vw,76px)}
.post-body h2{margin-top:2.3em}
.post-body h3{margin-top:2em}
.post-body blockquote{margin:2rem 0;padding:18px 24px;border-left:4px solid var(--yohaku-lime);background:var(--yohaku-surface-soft)}
.post-body a{text-decoration-thickness:1px}
.post-navigation{max-width:880px;margin:64px auto 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--yohaku-rule)}
.post-navigation .wp-block-post-navigation-link{background:var(--yohaku-surface);padding:22px 24px;min-height:88px}

/* One breakpoint model: mobile <= 767, tablet 768-1023, desktop >= 1024. */
@media(max-width:1023px){
 .wp-block-navigation__responsive-container:not(.is-menu-open){display:none!important}
 .wp-block-navigation__responsive-container-open{display:flex!important}
 .wp-block-navigation__responsive-container.is-menu-open{display:flex!important;padding:28px}
 .wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item{font-size:18px;line-height:1.35}
 .site-header{gap:16px}
 .header-actions{margin-left:auto;gap:12px}
 .wp-block-buttons.header-cta{display:flex!important}
 .section-header,.split-grid,.hero-grid,.page-header-grid,.about-story-grid,.values-head,.contact-layout,.footer-main{grid-template-columns:1fr}
 .section-header__copy,.page-header .wp-block-post-excerpt{justify-self:start}
 .contact-guide{position:static}
 .hero-visual::before{inset:14px -12px -14px 12px;border-radius:92px 6px 6px 6px}
 .hero-visual img{aspect-ratio:16/10;border-radius:92px 6px 6px 6px;object-position:center 42%}
 .service-row{grid-template-columns:56px minmax(0,1fr) auto}
 .service-row__outcome{grid-column:2/4}
 .case-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .case-step,.case-step+.case-step,.case-step:nth-child(3),.case-step:nth-child(4){padding:26px 22px;border-left:0;border-top:1px solid rgba(255,255,255,.25);min-height:0}
 .case-step:nth-child(-n+2){border-top:0}
 .case-step:nth-child(even){border-left:1px solid rgba(255,255,255,.25)}
 .process-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .process-step,.process-step+.process-step,.process-step:nth-child(4),.process-step:nth-child(5){padding:24px 20px;border-left:0;border-top:1px solid var(--yohaku-rule);min-height:0}
 .process-step:nth-child(-n+2){border-top:0}
 .process-step:nth-child(even){border-left:1px solid var(--yohaku-rule)}
 .footer-cta{grid-template-columns:1fr;align-items:start}
}
@media(max-width:767px){
 .wp-block-buttons.header-cta{display:none!important}
 .service-row{grid-template-columns:40px minmax(0,1fr)}
 .service-row__outcome,.service-row__arrow{grid-column:2}
 .service-row__arrow{justify-content:flex-start}
 .case-grid,.process-grid,.resource-grid,.post-navigation{grid-template-columns:1fr}
 .case-step,.case-step+.case-step,.case-step:nth-child(3),.case-step:nth-child(4){border-left:0;border-top:1px solid rgba(255,255,255,.25);padding:22px 0}
 .case-step:first-child{border-top:0}
 .process-step,.process-step+.process-step,.process-step:nth-child(4),.process-step:nth-child(5){border-left:0;border-top:1px solid var(--yohaku-rule);padding:18px 0}
 .process-step:first-child{border-top:0}
 .resource-card,.resource-card:nth-child(even){padding:26px 0;border-left:0}
 .company-profile__row{grid-template-columns:1fr;gap:8px}
 .post-hero h1{max-width:none}
}
@media(min-width:1024px){.brand-subtitle{display:block}}
@media(prefers-reduced-motion:reduce){.skip-link{transition:none}}

