*{box-sizing:border-box}
:root{
 --yohaku-rule:#d7dfd5;
 --yohaku-rule-strong:#b9c8bb;
 --yohaku-surface:#fff;
 --yohaku-surface-soft:#eef2e9;
 --yohaku-ink:#193c35;
 --yohaku-forest:#163d35;
 --yohaku-muted:#52665e;
 --yohaku-lime:#d9ec9b;
 --yohaku-section-space:clamp(72px,8vw,124px);
 --yohaku-grid-gap:clamp(28px,4vw,64px);
 --yohaku-radius:10px;
}
html{scroll-behavior:smooth}
body{margin:0}
body,button,input,textarea,select{text-rendering:optimizeLegibility}
body,p,li{line-break:strict;word-break:normal;overflow-wrap:anywhere}
a{text-underline-offset:5px}
a:hover{text-decoration-thickness:2px}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #456b26;outline-offset:5px}
img{max-width:100%;height:auto}
p{margin-top:0}
h1,h2,h3{text-wrap:balance}
.wp-block-heading{scroll-margin-top:90px}
.site-main{margin-top:0;min-height:60vh}
.site-main>.wp-block-post-content{max-width:none}
.eyebrow{font-size:11px;font-weight:800;letter-spacing:.18em;line-height:1.5;margin:0 0 16px;color:var(--yohaku-muted)}
.section-shell{position:relative;padding-block:var(--yohaku-section-space);border-top:1px solid var(--yohaku-rule)}
.section-shell--no-rule{border-top:0}
.section-header{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--yohaku-grid-gap);align-items:start;margin-bottom:clamp(38px,5vw,68px)}
.section-header__title h2,.section-header>h2{font-size:clamp(32px,3.5vw,50px);line-height:1.28;letter-spacing:-.03em;margin:0}
.section-header__copy{max-width:44rem;justify-self:end}
.section-header__copy>p:last-child{margin-bottom:0}
.section-lead{font-size:clamp(18px,1.55vw,23px);line-height:1.8;margin-bottom:20px}
.split-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--yohaku-grid-gap);align-items:start}
.content-measure{max-width:44rem}
.wide-content{max-width:none}
.rule-link{font-size:13px;font-weight:750;text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:3px}
.number-label{font-size:11px;font-weight:800;letter-spacing:.18em;color:var(--yohaku-muted)}
.wp-block-button__link{transition:transform .18s ease,box-shadow .18s ease,background .18s ease,border-color .18s ease}
.wp-block-button__link:hover{transform:translateY(-1px);box-shadow:0 7px 18px rgba(22,61,53,.12)}
.wp-block-button.is-style-outline a{background:transparent;border:1px solid var(--yohaku-forest);color:var(--yohaku-forest)}
/* Header */
header.wp-block-template-part{background:rgba(247,248,242,.96);border-bottom:1px solid var(--yohaku-rule);backdrop-filter:blur(10px);position:relative;z-index:20}
.site-header{padding-block:18px;gap:30px}
.header-brand{display:flex;align-items:center;gap:14px}
.brand{font-size:21px;font-weight:800;letter-spacing:.08em;line-height:1.2}
.brand a{text-decoration:none}
.brand::before{content:"";display:inline-block;width:10px;height:10px;background:var(--yohaku-lime);border:1px solid var(--yohaku-forest);margin-right:10px;vertical-align:1px}
.brand-subtitle{font-size:9px;letter-spacing:.17em;color:var(--yohaku-muted);margin:4px 0 0;text-transform:uppercase}
.header-actions{display:flex;align-items:center;gap:22px}
.wp-block-navigation{font-size:12px;font-weight:700}
.wp-block-navigation__container{gap:23px}
.wp-block-navigation a{position:relative;text-decoration:none}
.wp-block-navigation a::after{content:"";position:absolute;left:0;right:100%;bottom:-6px;height:1px;background:var(--yohaku-forest);transition:right .2s ease}
.wp-block-navigation a:hover::after{right:0}
.header-cta .wp-block-button__link{font-size:12px;padding:11px 17px}
.demo-note{font-size:11px;letter-spacing:.06em;color:var(--yohaku-muted)}
/* Hero */
.hero{position:relative;padding-block:clamp(72px,8vw,116px) clamp(88px,9vw,132px)}
.hero::before{content:"01 / INTRO";position:absolute;top:36px;right:0;font-size:10px;font-weight:800;letter-spacing:.2em;color:#84978a}
.hero-grid{grid-template-columns:minmax(0,7fr) minmax(300px,5fr);align-items:center}
.hero-copy{padding-right:clamp(0px,2vw,24px)}
.hero h1{max-width:10.8em;font-size:clamp(44px,5.35vw,78px);line-height:1.14;letter-spacing:-.04em;margin:18px 0 28px}
.hero-lead{max-width:42rem;font-size:17px;line-height:1.95;margin-bottom:30px}
.hero .wp-block-buttons{gap:10px 12px}
.hero .wp-block-button__link{min-width:150px;text-align:center}
.hero-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:42px;padding-top:18px;border-top:1px solid var(--yohaku-rule)}
.hero-meta p{font-size:10px;line-height:1.5;letter-spacing:.13em;color:var(--yohaku-muted);margin:0}
.hero-visual{position:relative;margin:0}
.hero-visual::before{content:"";position:absolute;inset:24px -24px -24px 24px;border:1px solid #c9d2c4;border-radius:180px 10px 10px 10px;z-index:-1}
.hero-visual::after{content:"";position:absolute;width:82px;height:82px;border-radius:50%;right:-14px;bottom:34px;background:var(--yohaku-lime);mix-blend-mode:multiply;opacity:.9}
.hero-visual img{width:100%;aspect-ratio:4/5;object-fit:cover;display:block;border-radius:180px 10px 10px 10px}
.hero-visual figcaption{font-size:9px;text-align:right;color:var(--yohaku-muted);letter-spacing:.18em;margin-top:12px}
/* Approach */
.approach{background:linear-gradient(180deg,rgba(233,237,227,.35),rgba(247,248,242,0))}
.approach .section-header{margin-bottom:0}
.approach .section-header__copy{padding-top:2px}
.approach-callout{font-size:clamp(21px,2vw,29px);line-height:1.7;margin:0 0 24px;padding-left:22px;border-left:4px solid var(--yohaku-lime)}
.approach-body{max-width:40rem;line-height:1.95}
/* Services index */
.service-index{border-top:1px solid var(--yohaku-rule-strong)}
.service-row{display:grid;grid-template-columns:72px minmax(0,1.25fr) minmax(220px,.9fr) auto;gap:clamp(18px,3vw,44px);align-items:start;padding:30px 0;border-bottom:1px solid var(--yohaku-rule)}
.service-row:hover .service-row__arrow{transform:translateX(4px)}
.service-row__number{font-size:11px;font-weight:800;letter-spacing:.18em;color:var(--yohaku-muted);padding-top:8px}
.service-row h3{font-size:clamp(23px,2vw,31px);line-height:1.35;margin:0 0 10px}
.service-row__keyword{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--yohaku-muted);margin-bottom:8px}
.service-row__desc{font-size:15px;line-height:1.85;margin-bottom:0}
.service-row__outcome{font-size:13px;line-height:1.8;color:var(--yohaku-muted);margin:0}
.service-row__arrow{font-size:20px;line-height:1;transition:transform .18s ease}
.service-row a{text-decoration:none}
/* Demo case */
.demo-case{background:var(--yohaku-forest);color:#fff;border-top:0}
.demo-case .eyebrow,.demo-case .number-label{color:var(--yohaku-lime)}
.demo-case h2,.demo-case h3,.demo-case a{color:#fff}
.demo-case .section-header__copy{color:#e6eee8}
.case-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid rgba(255,255,255,.28);border-bottom:1px solid rgba(255,255,255,.28)}
.case-step{padding:28px 24px 28px 0;min-height:220px}
.case-step+.case-step{border-left:1px solid rgba(255,255,255,.25);padding-left:24px}
.case-step h3{font-size:17px;margin:16px 0 12px}
.case-step p{font-size:13px;line-height:1.85;color:#e6eee8;margin:0}
.case-note{font-size:11px;letter-spacing:.05em;color:#c6d7ca;margin:20px 0 0}
/* Editorial news */
.news-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end;margin-bottom:36px}
.news-head h2{font-size:clamp(32px,3.5vw,50px);margin:0}
.news-head .wp-block-buttons{margin:0}
.news-featured{padding:0;list-style:none;margin:0}
.news-featured>li{display:grid;grid-template-columns:minmax(260px,5fr) minmax(0,7fr);gap:var(--yohaku-grid-gap);align-items:center;padding-bottom:42px;border-bottom:1px solid var(--yohaku-rule-strong)}
.news-featured .wp-block-post-featured-image{margin:0}
.news-featured .wp-block-post-featured-image img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:4px}
.news-featured .wp-block-post-date,.news-featured .wp-block-post-terms,.news-compact .wp-block-post-date,.news-compact .wp-block-post-terms{font-size:11px;color:var(--yohaku-muted)}
.news-featured .wp-block-post-title{font-size:clamp(24px,2.5vw,34px);line-height:1.45;margin:14px 0}
.news-featured .wp-block-post-excerpt{font-size:14px;line-height:1.85}
.news-compact{list-style:none;padding:0;margin:0}
.news-compact>li{display:grid;grid-template-columns:112px 110px minmax(0,1fr);gap:20px;align-items:baseline;padding:23px 0;border-bottom:1px solid var(--yohaku-rule)}
.news-compact .wp-block-post-title{font-size:17px;line-height:1.6;margin:0}
.news-editorial .wp-block-query-pagination{display:none}
/* Compact CMS demo */
.cms-demo{background:var(--yohaku-surface-soft);border-top:1px solid #c9d2c4}
.cms-demo-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--yohaku-grid-gap);align-items:start}
.cms-demo h2{font-size:clamp(30px,3vw,46px);line-height:1.3;margin:0 0 22px}
.cms-demo__lead{font-size:16px;line-height:1.9;max-width:39rem}
.cms-demo-list{border-top:1px solid #c5d0c2}
.cms-demo-item{display:grid;grid-template-columns:58px 1fr auto;gap:16px;padding:18px 0;border-bottom:1px solid #c5d0c2;align-items:center}
.cms-demo-item p{margin:0;font-size:13px;line-height:1.6}
.cms-demo-item a{font-size:12px;font-weight:750;white-space:nowrap}
.cms-demo .wp-block-buttons{margin-top:28px}
/* CTA */
.band{position:relative;overflow:hidden;background:var(--yohaku-forest);color:#fff;padding:clamp(40px,5vw,68px);border-radius:var(--yohaku-radius)}
.band::before{content:"";position:absolute;left:0;top:0;width:90px;height:5px;background:var(--yohaku-lime)}
.band::after{content:"";position:absolute;width:260px;height:260px;border-radius:50%;right:-78px;top:-104px;background:var(--yohaku-lime);opacity:.14}
.band .eyebrow{color:var(--yohaku-lime)}
.band h2{position:relative;color:#fff;font-size:clamp(31px,3.5vw,50px);line-height:1.3;margin:0 0 18px}
.band p{position:relative;max-width:44rem;line-height:1.9}
.band a{color:#fff}
.band .wp-block-button__link{background:var(--yohaku-lime);color:var(--yohaku-forest)}
/* Page header */
.page-header{position:relative;padding-block:clamp(58px,7vw,94px) clamp(42px,5vw,62px);border-bottom:1px solid var(--yohaku-rule)}
.page-header::after{content:"";position:absolute;width:64px;height:4px;background:var(--yohaku-lime);left:0;bottom:-2px}
.page-header-grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(280px,5fr);gap:var(--yohaku-grid-gap);align-items:end}
.page-header h1{font-size:clamp(38px,4.5vw,64px);line-height:1.18;letter-spacing:-.04em;margin:10px 0 0}
.page-header .wp-block-post-excerpt{max-width:39rem;justify-self:end}
.page-header .wp-block-post-excerpt__excerpt{font-size:16px;line-height:1.9;margin:0}
.page-content{padding-block:0 90px}
.page-content>.wp-block-post-content{padding-top:clamp(54px,6vw,82px)}
.page-content h2{line-height:1.4;margin-top:0}
.page-content p{line-height:1.9}
.page-content .wp-block-table td{border:0;border-bottom:1px solid var(--yohaku-rule);padding:18px 10px;font-size:15px}
.page-content .wp-block-table td:first-child{width:28%;font-weight:650}
.page-content .wp-block-table table{border-collapse:collapse}
.page-lead{max-width:48rem;font-size:clamp(19px,1.7vw,24px);line-height:1.8;margin-bottom:48px}
/* About */
.about-story{margin-bottom:var(--yohaku-section-space)}
.about-story-grid{display:grid;grid-template-columns:minmax(0,6fr) minmax(300px,6fr);gap:var(--yohaku-grid-gap);align-items:center}
.about-story h2{font-size:clamp(30px,3vw,45px);margin:0 0 24px}
.about-story .wp-block-image{margin:0;position:relative}
.about-story .wp-block-image::before{content:"";position:absolute;inset:-16px 18px 18px -16px;border:1px solid var(--yohaku-rule-strong);z-index:-1}
.about-story img{width:100%;aspect-ratio:5/4;object-fit:cover}
.values-section{border-top:1px solid var(--yohaku-rule-strong);padding-top:36px}
.values-head{display:grid;grid-template-columns:5fr 7fr;gap:var(--yohaku-grid-gap);margin-bottom:18px}
.values-head h2{font-size:clamp(28px,2.8vw,42px);margin:0}
.value-row{display:grid;grid-template-columns:80px minmax(0,4fr) minmax(0,7fr);gap:24px;padding:26px 0;border-bottom:1px solid var(--yohaku-rule)}
.value-row h3{font-size:21px;margin:0}
.value-row p{margin:0}
.portfolio-disclaimer{margin-top:44px;border-left:3px solid var(--yohaku-lime);padding:16px 20px;background:#f0f2eb;font-size:12px;color:var(--yohaku-muted)}
/* Services detail */
.service-detail{padding:42px 0;border-top:1px solid var(--yohaku-rule-strong)}
.service-detail-grid{display:grid;grid-template-columns:92px minmax(0,4fr) minmax(0,7fr);gap:clamp(20px,3vw,42px);align-items:start}
.service-detail h2{font-size:clamp(29px,2.8vw,42px);margin:0}
.service-detail__body>.eyebrow{margin-bottom:12px}
.service-detail__body h3{font-size:13px;letter-spacing:.12em;margin:28px 0 10px}
.service-detail__body ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.service-detail__body li{font-size:12px;border:1px solid var(--yohaku-rule-strong);background:#fff;padding:8px 10px;border-radius:999px}
.service-outcome{margin-top:24px;padding:18px 20px;background:var(--yohaku-surface-soft);font-size:14px;line-height:1.8}
.process-section{margin-top:64px;padding-top:42px;border-top:1px solid var(--yohaku-rule-strong)}
.process-section h2{font-size:clamp(28px,2.8vw,42px);margin:0 0 32px}
.process-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border-top:1px solid var(--yohaku-rule-strong);border-bottom:1px solid var(--yohaku-rule-strong)}
.process-step{padding:24px 18px 26px 0;min-height:150px}
.process-step+.process-step{border-left:1px solid var(--yohaku-rule);padding-left:18px}
.process-step h3{font-size:15px;margin:12px 0 8px}
.process-step p{font-size:12px;line-height:1.75;margin:0}
/* Contact */
.contact-layout{display:grid;grid-template-columns:minmax(0,5fr) minmax(340px,7fr);gap:var(--yohaku-grid-gap);align-items:start}
.contact-guide{position:sticky;top:32px}
.contact-guide h2{font-size:clamp(29px,3vw,44px);margin:0 0 20px}
.contact-examples{margin:30px 0 0;padding:0;list-style:none;border-top:1px solid var(--yohaku-rule)}
.contact-examples li{padding:16px 0;border-bottom:1px solid var(--yohaku-rule);font-size:14px}
.contact-meta{font-size:12px;color:var(--yohaku-muted);margin-top:26px}
.form-panel{background:#fff;border:1px solid var(--yohaku-rule);padding:clamp(26px,4vw,44px)}
.form-panel .form-notice{margin-top:0}
/* Generic news/archive */
.news-list{padding:0;list-style:none}
.news-list>li{display:grid;grid-template-columns:110px minmax(0,1fr);column-gap:28px;border-bottom:1px solid var(--yohaku-rule);padding:28px 0}
.news-list h2,.news-list h3{grid-column:2;font-size:19px;line-height:1.55;margin:4px 0 8px}
.news-list time,.wp-block-post-terms{font-size:12px;color:var(--yohaku-muted)}
.news-list .wp-block-post-date{grid-column:1;grid-row:1/4}
.news-list .wp-block-post-terms{grid-column:2}
.news-list .wp-block-post-excerpt{grid-column:2;font-size:14px;line-height:1.8}
/* Footer */
.footer-wrap{background:#e9ede3;border-top:1px solid #d5ddd0}
.site-footer{padding-block:clamp(52px,6vw,82px) 28px}
.footer-cta{display:grid;grid-template-columns:minmax(0,8fr) auto;gap:32px;align-items:end;padding-bottom:42px;margin-bottom:40px;border-bottom:1px solid #c9d2c4}
.footer-cta h2{font-size:clamp(28px,3vw,44px);line-height:1.3;margin:0}
.footer-main{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--yohaku-grid-gap)}
.footer-brand-copy{max-width:28rem}
.footer-nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
.footer-nav h3{font-size:10px;letter-spacing:.17em;color:var(--yohaku-muted);margin:0 0 14px}
.footer-nav p{margin:0 0 8px}
.footer-nav a{font-size:13px;text-decoration:none}
.site-footer .brand{font-size:24px}
.copyright{font-size:10px;color:var(--yohaku-muted);border-top:1px solid #c9d2c4;padding-top:20px;margin-top:38px}
/* Posts, forms and utility */
.post-hero{max-width:760px;padding-top:60px}
.post-hero h1{font-size:clamp(29px,4vw,46px);line-height:1.35}
.post-hero img{border-radius:8px}
.wp-block-post-navigation-link{padding:20px 0}
.wp-block-query-pagination{margin-top:30px}
.not-found-card{max-width:880px;margin-top:48px;margin-bottom:72px;padding:clamp(34px,5vw,62px);background:#fff;border:1px solid var(--yohaku-rule);border-radius:12px}
.not-found-card .wp-block-search{max-width:560px}
.demo-form{margin:22px 0 0}
.demo-form label{display:block;font-size:14px;font-weight:650;margin-top:24px}
.demo-form input:not([type=checkbox]),.demo-form textarea,.demo-form select{width:100%;font:inherit;padding:12px;background:white;color:var(--yohaku-ink);border:1px solid #84978a;border-radius:4px;display:block;margin-top:8px}
.demo-form textarea{min-height:160px}
.demo-form input[type=checkbox]{width:20px;height:20px;vertical-align:middle;margin-right:8px}
.demo-form button{font:inherit;color:white;background:var(--yohaku-forest);border:0;padding:16px 30px;border-radius:4px;margin-top:24px;cursor:pointer;transition:transform .18s ease,background .18s ease}
.demo-form button:not(:disabled):hover{transform:translateY(-1px);background:#0d2b25}
.demo-form button:disabled{opacity:.5;cursor:default}
.form-notice{border-left:3px solid var(--yohaku-forest);background:#e9ede3;padding:18px 20px;font-size:13px}
.form-success{padding:24px;background:#e9ede3;border:1px solid #809365;margin-top:24px}
.required{font-size:11px;margin-left:8px;color:var(--yohaku-muted)}
.wp-block-search__input{border:1px solid #84978a;padding:12px}
.wp-block-search__button{background:var(--yohaku-forest);color:#fff;border:0}
.wp-block-navigation__responsive-container.is-menu-open{padding:32px}
.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item{font-size:20px}
.editor-styles-wrapper .hero{padding-block:50px}
.editor-styles-wrapper .section-shell{padding-block:54px}
.editor-styles-wrapper .cms-demo{margin-top:20px}
/* Responsive */
@media(max-width:1024px){
 .header-actions{gap:14px}
 .wp-block-navigation__container{gap:16px}
 .brand-subtitle{display:none}
 .hero-grid{grid-template-columns:minmax(0,6fr) minmax(280px,5fr)}
 .service-row{grid-template-columns:56px minmax(0,1.2fr) minmax(190px,.9fr) auto}
 .case-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .case-step:nth-child(3){border-left:0;border-top:1px solid rgba(255,255,255,.25);padding-left:0}
 .case-step:nth-child(4){border-top:1px solid rgba(255,255,255,.25)}
 .process-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
 .process-step:nth-child(4){border-left:0;border-top:1px solid var(--yohaku-rule);padding-left:0}
 .process-step:nth-child(5){border-top:1px solid var(--yohaku-rule)}
}
@media(max-width:781px){
 .site-header{padding-block:15px}
 .header-cta{display:none}
 .header-actions{margin-left:auto}
 .wp-block-navigation__container{gap:18px}
 .section-header,.split-grid,.hero-grid,.cms-demo-grid,.page-header-grid,.about-story-grid,.values-head,.contact-layout,.footer-main{grid-template-columns:1fr}
 .section-header__copy,.page-header .wp-block-post-excerpt{justify-self:start}
 .section-shell{padding-block:62px}
 .hero{padding-block:58px 72px}
 .hero::before{top:24px}
 .hero-copy{padding-right:0}
 .hero h1{max-width:11em;font-size:clamp(40px,11vw,56px);line-height:1.17;margin-bottom:22px}
 .hero-lead{font-size:16px;line-height:1.85}
 .hero-meta{margin-top:30px}
 .hero-visual{margin-top:14px}
